<script setup lang="ts">
import{computed,ref}from'vue';import Taro,{useLoad}from'@tarojs/taro';import PageShell from '@/components/PageShell.vue';import SectionCard from '@/components/SectionCard.vue';import StatePanel from '@/components/StatePanel.vue';import FactRow from '@/components/FactRow.vue';import StatusBadge from '@/components/StatusBadge.vue';import{api}from'@/lib/api';import{errorMessage}from'@/lib/errors';import{dateKey,fundingLabel,minorFromYuan,yuan}from'@/lib/format';import type{Adjustment,BudgetPeriod}from'@/lib/types';
const period=ref<BudgetPeriod|null>(null),periodId=ref(''),amount=ref('400'),plannedOn=ref(dateKey(new Date().toISOString())),reason=ref('临时必要支出'),proposal=ref<Adjustment|null>(null),selected=ref(''),loading=ref(true),saving=ref(false),error=ref('');async function loadPeriod(){period.value=(await api.period(periodId.value)).data;if(plannedOn.value<period.value.period.monthStart||plannedOn.value>period.value.period.monthEnd)plannedOn.value=period.value.period.monthStart;}useLoad(async o=>{periodId.value=o.periodId??'';try{await loadPeriod();}catch(e){error.value=errorMessage(e);}finally{loading.value=false;}});
const minimumOn=computed(()=>{const today=dateKey(new Date().toISOString());return period.value&&period.value.period.monthStart>today?period.value.period.monthStart:today;});
async function assess(){if(!period.value||saving.value)return;if(plannedOn.value<dateKey(new Date().toISOString())||plannedOn.value<period.value.period.monthStart||plannedOn.value>period.value.period.monthEnd){error.value='请选择本周期今天或之后的待安排日期；已发生支出请到账目页核对流水。';return;}const minor=minorFromYuan(amount.value);if(!minor){error.value='请输入有效金额。';return;}saving.value=true;error.value='';selected.value='';try{proposal.value=(await api.assessEmergency({periodId:period.value.period.periodId,amountMinor:minor,plannedOn:plannedOn.value,reason:reason.value,expectedFinancialVersion:period.value.basis.financialVersion,expectedPeriodVersion:period.value.basis.periodVersion})).data;}catch(e){error.value=errorMessage(e);}finally{saving.value=false;}}
async function confirm(){if(!proposal.value||!selected.value||saving.value)return;const currentProposal=proposal.value,optionId=selected.value;saving.value=true;try{const ok=await Taro.showModal({title:'确认采用这项调整？',content:'只执行你选中的方案；涉及订单善后时会继续保留渠道和到账状态。',confirmText:'确认调整'});if(!ok.confirm)return;await api.confirmAdjustment(currentProposal.adjustmentId,{acceptedOptionId:optionId,expectedFinancialVersion:currentProposal.basisFinancialVersion,expectedPeriodVersion:currentProposal.basisPeriodVersion,confirmedByUser:true});await Taro.redirectTo({url:`/pages/adjustment/detail?id=${currentProposal.adjustmentId}`});}catch(e){error.value=errorMessage(e);}finally{saving.value=false;}}
async function resetProposal(){proposal.value=null;selected.value='';error.value='';loading.value=true;try{await loadPeriod();}catch(e){error.value=errorMessage(e);}finally{loading.value=false;}}
function changeLabel(change:Record<string,unknown>){const action=String(change.action??'adjust');const title=String(change.title??change.itemTitle??'计划项目');if(action==='cancel_order')return `申请取消订单：${title}`;if(action==='cancel')return `取消计划项目：${title}`;return `调整：${title}`;}
</script>
<template><PageShell title="记录意外支出" subtitle="这是规划评估，不会新增银行流水" compact><template #hero><button class="back" @tap="Taro.navigateBack()">‹</button></template><StatePanel v-if="loading" title="正在读取资金依据"/><template v-else><view class="notice notice--info boundary-note">这里记录的是预算中的意外安排，不是新增一笔银行已入账流水。确认前会先评估对本月资金的影响。</view><SectionCard><template v-if="!proposal"><label class="field"><text>金额（元）</text><input v-model="amount" type="digit"/></label><label class="field"><text>待安排日期</text><picker mode="date" :start="minimumOn" :end="period?.period.monthEnd" :value="plannedOn" @change="plannedOn=String(($event.detail as any).value)"><view class="picker-value">{{plannedOn}} ›</view></picker></label><label class="field"><text>原因</text><input v-model="reason" maxlength="200"/></label><button class="primary-button full" :loading="saving" @tap="assess">评估资金影响</button></template><template v-else><view class="row-between"><text class="title">基准判断</text><StatusBadge :label="fundingLabel(proposal.baseline.status)" tone="warning"/></view><FactRow label="意外支出" :value="yuan(proposal.emergency.amountMinor)"/><FactRow label="预计缺口" :value="yuan(proposal.baseline.shortfallMinor)" emphasis/><text class="heading">请选择一个调整方案</text><button v-for="option in proposal.options" :key="option.optionId" class="option" :class="{'option--active':selected===option.optionId}" @tap="selected=option.optionId"><view><text>{{option.label}}</text><text>{{fundingLabel(option.assessment.status)}} · 缺口 {{yuan(option.assessment.shortfallMinor)}}</text><text v-for="(change,index) in option.changes" :key="index" class="change">{{changeLabel(change)}}</text></view><text>{{selected===option.optionId?'✓':'○'}}</text></button><button class="primary-button full" :loading="saving" :disabled="!selected||saving" @tap="confirm">{{selected?'确认所选方案':'请先选择方案'}}</button><button class="secondary-button full" :disabled="saving" @tap="resetProposal">修改金额或日期并重新评估</button></template><view v-if="error" class="notice notice--error err">{{error}}</view></SectionCard></template></PageShell></template>
<style lang="scss">@use '../../styles/tokens' as *;.back{position:absolute;right:28px;top:calc(34px + env(safe-area-inset-top));width:64px;height:64px;border-radius:50%;font-size:44px}.boundary-note{margin-bottom:24px;font-size:28px;line-height:1.6}.field{display:block;margin-bottom:36px}.field text{display:block;margin-bottom:14px;color:$text-secondary;font-size:28px;font-weight:620}.field input,.picker-value{height:96px;padding:0 24px;background:$soft-surface;border:2px solid $border;border-radius:22px;font-size:30px;line-height:96px}.field:first-child input{font-size:38px;font-weight:720}.full{width:100%;margin-top:24px}.title,.heading{font-size:36px;font-weight:740}.heading{display:block;margin:30px 0 16px}.option{display:flex;width:100%;min-height:132px;align-items:flex-start;justify-content:space-between;gap:18px;padding:24px;text-align:left;border:2px solid $border;border-radius:24px}.option+.option{margin-top:16px}.option>view{min-width:0;flex:1}.option>text:last-child{font-size:34px}.option text{display:block}.option view text:first-child{font-size:31px;font-weight:690}.option view text+text{margin-top:9px;color:$text-secondary;font-size:27px;line-height:1.5}.option .change{padding-left:18px;color:$text-tertiary;font-size:25px}.option--active{background:$surface-tint;border-color:$brand-primary}.err{margin-top:22px;font-size:28px}</style>
